/// <summary>
/// designed from AVA
/// </summary>
[ExtensionOf(formControlStr(SalesQuotationTable,AVAQuotExcel))]
internal final class AVASalesQuotationTableFrm_AVAQuotExcel_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
public void clicked()
{
    SalesQuotationTable     salesQuotationTable;
    CustQuotationSalesLink    custQuotationSalesLink;
    CustQuotationJour         custQuotationJour;

    next clicked();

    FormControl curButton = any2Object(this) as FormControl;
    FormDataSource          quotationDS = curButton.formRun().dataSource(tableStr(SalesQuotationTable));
    if (quotationDS)
    {
        salesQuotationTable = quotationDS.cursor();
    }

    select firstonly TableId from custQuotationSalesLink
            order by QuotationDate desc, QuotationId desc
            where custQuotationSalesLink.OrigQuotationId == salesQuotationTable.QuotationId
        join  custQuotationJour
            where custQuotationJour.QuotationId == custQuotationSalesLink.QuotationId   &&
                  custQuotationJour.QuotationDate   == custQuotationSalesLink.QuotationDate;


    Args    args = new Args();
    MenuFunction        menuFunction;
    args.record(custQuotationJour); 
    args.caller(curButton.formRun());

    menuFunction = new MenuFunction(menuitemOutputStr(SalesQuotationCopy), MenuItemType::Output);
    menuFunction.run(args);
}
